// Monospace bitmap fonts (Courier Prime at the sizes the Pi version uses).
// Glyph data is in fonts.cpp, generated by tools/gen_font.py.
#pragma once
#include <stddef.h>
#include <stdint.h>

struct Font {
  uint8_t w;         // cell width = character advance
  uint8_t h;         // cell height
  uint8_t rowBytes;  // bytes per glyph row
  uint8_t ascent;    // baseline is `ascent` rows below the cell top
  const uint8_t *glyphs;  // 95 glyphs (ASCII 32..126), h * rowBytes bytes each, 1 = ink

  // Bitmap for a character; anything outside 32..126 shows as '?'.
  const uint8_t *glyph(char c) const {
    int i = (c < 32 || c > 126) ? ('?' - 32) : (c - 32);
    return glyphs + (size_t)i * h * rowBytes;
  }
};

extern const Font FONT_18, FONT_20, FONT_26, FONT_28, FONT_32;
